INSERT INTO `content_ml` VALUES (242, 13, 'hy', 'Նուբարաշենի աղբավայրում կեսգիշերին ուժեղ հրդեհ է բռնկվել ողջ գիշեր աշխատել են փրկարարներն ու ջրցան մեքենաները', '', 'Նուբարաշենի աղբավայրում կեսգիշերին ուժեղ հրդեհ է բռնկվել ողջ գիշեր աշխատել են փրկարարներն ու ջրցան մեքենաները');
INSERT INTO `content_ml` VALUES (243, 13, 'ru', 'Նուբարաշենի աղբավայրում կեսգիշերին ուժեղ հրդեհ է բռնկվել ողջ գիշեր աշխատել են փրկարարներն ու ջրցան մեքենաները', '', 'Նուբարաշենի աղբավայրում կեսգիշերին ուժեղ հրդեհ է բռնկվել ողջ գիշեր աշխատել են փրկարարներն ու ջրցան մեքենաները');
